Subject: [PATCH] KeySequenceItem: make the conflict dialog block its window

The settings window could be closed under the shortcut conflict dialog.
The dialog had no parent window, so its window modality blocked nothing.
Make it and the error dialog transient for the shortcut's window.

BUG: 519304
---
 .../kquickcontrols/private/keysequencehelper.cpp          | 8 ++++++++
 1 file changed, 8 insertions(+)

diff --git a/src/qmlcontrols/kquickcontrols/private/keysequencehelper.cpp b/src/qmlcontrols/kquickcontrols/private/keysequencehelper.cpp
index a58c88fe..9c8e0ef7 100644
--- a/src/qmlcontrols/kquickcontrols/private/keysequencehelper.cpp
+++ b/src/qmlcontrols/kquickcontrols/private/keysequencehelper.cpp
@@ -72,6 +72,10 @@ void KeySequenceHelper::showErrorDialog(const QString &title, const QString &tex
     dialog->setCaption(title);
     dialog->setAttribute(Qt::WA_DeleteOnClose);
     dialog->setWindowModality(Qt::WindowModal);
+    if (window()) {
+        dialog->winId(); // so it creates the windowHandle()
+        dialog->windowHandle()->setTransientParent(window());
+    }
     connect(dialog, &KMessageDialog::finished, this, [this]() {
         Q_EMIT questionDialogRejected();
     });
@@ -88,6 +92,10 @@ void KeySequenceHelper::showQuestionDialog(const QString &title, const QString &
     dialog->setButtons(KStandardGuiItem::cont(), KStandardGuiItem::cancel());
     dialog->setAttribute(Qt::WA_DeleteOnClose);
     dialog->setWindowModality(Qt::WindowModal);
+    if (window()) {
+        dialog->winId(); // so it creates the windowHandle()
+        dialog->windowHandle()->setTransientParent(window());
+    }
     connect(dialog, &KMessageDialog::finished, this, [this](int result) {
         switch (result) {
         case KMessageDialog::PrimaryAction:
